It's because of this:
```js
  const args = ['./scripts/jest/jest.js', '--config'];
  if (argv.build) {
    args.push(buildConfig);
  } else if (argv.persistent) {
    args.push(persistentConfig);
  } else if (argv.project === 'devtools') {
    args.push(devToolsConfig);
  } else if (isWWWConfig()) {
    args.push(wwwConfig);
  } else if (isOSSConfig()) {
    args.push(ossConfig);
  } else {
    // We should not get here.
    logError('Unrecognized release channel');
    process.exit(1);
  }
```

DevTools uses both `build` *and* `project`
